from math import gcd
from Crypto.Util.number import long_to_bytes

n1 = int("", 16)
# a
n2 = int("", 16)
# b
c  = int("", 16)
e = 65537

p = gcd(n1, n2)   #最大共约数,p就是共享素数
q1 = n1 // p    # 分解 n1 求 q1
phi = (p - 1) * (q1 - 1)    # 
d = pow(e, -1, phi)     # py这里的 -1 是模逆元运算
m = pow(c, d, n1)     # c的d次方，取模得到明文m
print(long_to_bytes(m))     # 大整数按字节转成可读的 ASCII 字符串